INSERT INTO [dbo].[QuizQuestions]([QuestionText],[OptionA],[OptionB],[OptionC],[OptionD],[CorrectOption],[Level],[Explanation],[IsActive]) VALUES
(N'What TDP range is typical for a mid-range gaming CPU?', N'35-65W', N'65-125W', N'125-250W', N'250W+', N'B', N'Normal', N'Most gaming CPUs (e.g. Ryzen 5, Core i5) sit in the 65-125W TDP range. High-end chips can exceed 125W.', 1),
(N'Which PCIe slot is typically used for the primary GPU?', N'x1', N'x4', N'x8', N'x16', N'D', N'Normal', N'The top x16 slot offers full bandwidth for the GPU. Use the slot closest to the CPU for best performance.', 1),
(N'What does "dual channel" mean for RAM?', N'Two sticks in one slot', N'Two sticks in paired slots for doubled bandwidth', N'Two different RAM brands', N'RAM with two colors', N'B', N'Normal', N'Dual channel uses two matched sticks in the correct slots (often A2+B2) to double memory bandwidth.', 1),
(N'Which PSU efficiency rating is best for a gaming build?', N'80 Plus', N'80 Plus Bronze', N'80 Plus Gold', N'80 Plus Titanium', N'D', N'Normal', N'Titanium is the highest 80 Plus tier. Gold is a good balance of efficiency and cost for most builds.', 1),
(N'What is the main benefit of an M.2 NVMe SSD over SATA?', N'Larger capacity', N'Much faster read/write speeds', N'Lower price', N'Easier installation', N'B', N'Normal', N'NVMe uses PCIe lanes for far higher throughput than SATA. Gen4 NVMe can exceed 7000 MB/s.', 1),
(N'Which CPU cooler type is best for heavy overclocking?', N'Stock cooler', N'Low-profile air', N'Tower air or 240mm+ AIO', N'No cooler', N'C', N'Normal', N'Overclocking increases heat. A beefy tower or 240mm+ AIO provides the thermal headroom needed.', 1),
(N'What does "ATX" refer to in a motherboard?', N'CPU socket type', N'Form factor / size standard', N'RAM type', N'GPU interface', N'B', N'Normal', N'ATX is a form factor that defines board dimensions and mounting. Common sizes: ATX, micro-ATX, Mini-ITX.', 1),
(N'Why might you need a BIOS update before installing a new CPU?', N'To add more RAM', N'To support newer CPU generations on the same socket', N'To enable RGB', N'To fix GPU drivers', N'B', N'Normal', N'Motherboards may need a BIOS update to recognize newer CPUs on the same socket (e.g. Ryzen 5000 on B450).', 1),
(N'What is the purpose of case airflow?', N'To look good', N'To remove heat from components', N'To power the PC', N'To store data', N'B', N'Normal', N'Good airflow (intake + exhaust fans) moves hot air out and cool air in, keeping temps stable.', 1),
(N'Which factor most affects RAM compatibility with a motherboard?', N'Brand', N'DDR generation and speed', N'Color', N'Price', N'B', N'Normal', N'DDR4/DDR5 are not interchangeable. The board''s QVL lists tested speeds and capacities.', 1);
INSERT INTO [dbo].[QuizQuestions]([QuestionText],[OptionA],[OptionB],[OptionC],[OptionD],[CorrectOption],[Level],[Explanation],[IsActive]) VALUES
(N'What does CPU "boost clock" vs "base clock" indicate?', N'Same thing', N'Base = sustained, Boost = short burst max', N'Boost is for gaming only', N'Base is overclocked', N'B', N'Professional', N'Base clock is the guaranteed all-core speed. Boost allows higher single/light-thread speeds for short periods.', 1),
(N'Which PCIe generation roughly doubles bandwidth over the previous?', N'Same gen, different slot', N'Each new gen (3.0→4.0→5.0) doubles bandwidth', N'Only 5.0 matters', N'Gen does not affect bandwidth', N'B', N'Professional', N'PCIe 4.0 doubles 3.0; 5.0 doubles 4.0. x16 Gen4 = 32 GB/s; Gen5 = 64 GB/s.', 1),
(N'What is "thermal throttling"?', N'CPU runs faster when hot', N'CPU slows down to prevent overheating', N'Cooler stops working', N'GPU takes over', N'B', N'Professional', N'When temps hit the limit, the CPU reduces clock speed to stay within safe thermal envelope.', 1),
(N'Why might a 750W PSU be insufficient for a high-end build?', N'Always enough', N'Peak power spikes (e.g. RTX 4090) can exceed rated wattage', N'PSUs lose power over time', N'Voltage matters more', N'B', N'Professional', N'High-end GPUs have transient spikes. A 4090 + 13900K can momentarily draw well over 750W.', 1),
(N'What does "CL" in RAM timings (e.g. CL16) mean?', N'Capacity Level', N'Cas Latency - cycles to first data', N'Clock Level', N'Compatibility Level', N'B', N'Professional', N'CAS Latency is the delay (in cycles) from request to first data. Lower CL = faster response at same speed.', 1),
(N'Which cooling solution is best for extreme overclocking (LN2 aside)?', N'Stock cooler', N'120mm AIO', N'Custom loop or 360mm+ AIO', N'Passive heatsink', N'C', N'Professional', N'Custom loops and large AIOs dissipate the most heat, essential for pushing clocks on high-TDP chips.', 1),
(N'What is the main trade-off with smaller form factors (e.g. ITX)?', N'Cheaper', N'Limited expansion and cooling options', N'Faster performance', N'More RAM slots', N'B', N'Professional', N'ITX boards have fewer slots, smaller coolers fit, and cable management is tighter. Trade size for flexibility.', 1),
(N'Why might you use a "curve optimizer" or per-core offset?', N'To reduce FPS', N'To fine-tune voltage/clock per core for better efficiency', N'To disable cores', N'To change RAM speed', N'B', N'Professional', N'Curve optimizer (AMD) or per-core offsets (Intel) let you undervolt or tweak individual cores for stability and temps.', 1),
(N'What does "resizable BAR" (ReBAR) do?', N'Increases RAM size', N'Lets CPU access full GPU VRAM at once for better performance', N'Fixes driver bugs', N'Enables RGB sync', N'B', N'Professional', N'ReBAR allows the CPU to access the entire GPU frame buffer at once instead of 256MB chunks, improving some games.', 1),
(N'Which factor most affects 1% low FPS in games?', N'Monitor refresh rate', N'CPU single-thread and RAM latency', N'GPU brand', N'Case airflow', N'B', N'Professional', N'1% lows (frame time consistency) are often CPU and memory-bound. Fast RAM and strong single-thread help.', 1);
